float CreekZ(float x){return -68+6*Mathf.Sin(x/26)+.025f*x;}
float WaterY(float x){return 3.95f-.002f*x;}
float Base(float x,float z){float hills=Mathf.Pow(Mathf.Max(0,Mathf.Abs(x)-63)/95,1.45f)*23+Mathf.Pow(Mathf.Max(0,z-78)/75,1.45f)*15+Mathf.Pow(Mathf.Max(0,-z-130)/45,1.5f)*12;return 5.4f+.006f*(z+50)+.24f*Mathf.Sin(x/23)*Mathf.Cos(z/31)+.10f*Mathf.Sin(z/9+x/13)+hills;}
float S(float lo,float hi,float value){return Mathf.SmoothStep(0,1,Mathf.InverseLerp(lo,hi,value));}
float H(float x,float z){float h=Base(x,z);float delta=z-CreekZ(x);h=Mathf.Lerp(h,WaterY(x)-1.05f,Mathf.Exp(-delta*delta/22));float common=Mathf.Sqrt(x*x/(16*16)+(z-5)*(z-5)/(18*18));h=Mathf.Lerp(h,5.72f,1-S(.72f,1.25f,common));foreach(var b in sites){var v=Quaternion.Euler(0,-b.yaw,0)*new Vector3(x-b.x,0,z-b.z);float over=Mathf.Max(Mathf.Abs(v.x)-b.w*.5f,Mathf.Abs(v.z)-b.d*.5f);float weight=1-S(0,3,over);h=Mathf.Lerp(h,Base(b.x,b.z),weight);}return h;}
float bridgeZ=CreekZ(6),bridgeY=5.65f;
float RoadH(float x,float z,bool main){float y=H(x,z)+.075f;if(main&&Mathf.Abs(x-6)<5){float weight=1-S(9,19,Mathf.Abs(z-bridgeZ));y=Mathf.Lerp(y,bridgeY,weight);}return y;}
