System.Collections.Generic.List<Vector3> Route(string name,float width,bool main,Vector2[] knots){var pts=new System.Collections.Generic.List<Vector3>();for(int k=0;k<knots.Length-1;k++){var p0=knots[Mathf.Max(0,k-1)];var p1=knots[k];var p2=knots[k+1];var p3=knots[Mathf.Min(knots.Length-1,k+2)];int steps=Mathf.Max(3,Mathf.CeilToInt(Vector2.Distance(p1,p2)/.75f));for(int j=0;j<steps;j++){float t=(float)j/steps;var q=.5f*((2*p1)+(-p0+p2)*t+(2*p0-5*p1+4*p2-p3)*t*t+(-p0+3*p1-3*p2+p3)*t*t*t);pts.Add(new Vector3(q.x,RoadH(q.x,q.y,main),q.y));}}var last=knots[knots.Length-1];pts.Add(new Vector3(last.x,RoadH(last.x,last.y,main),last.y));var v=new System.Collections.Generic.List<Vector3>();var earthTri=new System.Collections.Generic.List<int>();var bridgeTri=new System.Collections.Generic.List<int>();for(int i=0;i<pts.Count;i++){var tangent=(pts[Mathf.Min(pts.Count-1,i+1)]-pts[Mathf.Max(0,i-1)]).normalized;var side=new Vector3(-tangent.z,0,tangent.x).normalized;float w=main&&Mathf.Abs(pts[i].z-bridgeZ)<12?4.8f:width;foreach(float sign in new[]{-1f,1f}){var q=pts[i]+side*w*.5f*sign;q.y=RoadH(q.x,q.z,main);v.Add(q);}if(i>0){int a=(i-1)*2;bool bridge=main&&Mathf.Abs((pts[i].z+pts[i-1].z)*.5f-bridgeZ)<9;var tris=bridge?bridgeTri:earthTri;tris.AddRange(new[]{a,a+1,a+2,a+1,a+3,a+2});}}if(earthTri.Count>0)Surface(name,v,earthTri,earth,routesRoot.transform,true);if(bridgeTri.Count>0)Surface("Bridge_ContinuousWalkDeck",v,bridgeTri,wood,routesRoot.transform,true);float length=0;for(int i=1;i<pts.Count;i++)length+=Vector3.Distance(pts[i-1],pts[i]);routeRecords.Add(new{name,widthMetres=width,mainRoad=main,lengthMetres=length,points=pts.Select(q=>new[]{q.x,q.y,q.z}).ToArray()});return pts;}
